    function __ESBMC_assume(bool) internal pure {}
    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash) public {
        bool reverted;
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, 0, bytes32(0), 0, 0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && c.number() == 0 && c.timestamp() == 0 && c.basefee() == 0);
    }
    receive() external payable {}
}

